function expandSeeds(seeds: QuestionSeed[]) {
  return seeds.map((seed, index) => {
    const [content, answer, distractors, explanation] = seed;
    const correctIndex = index % 4;
    const options = [...distractors];
    options.splice(correctIndex, 0, answer);
    return { content, options, correctIndex, explanation };
  });
}

export function getAdvancedQuestions(topicId: string) {
  return expandSeeds(ADVANCED_QUESTION_EXPANSION[topicId] ?? []);
}

export function getExpandedQuestions(topicId: string) {
  return expandSeeds(QUESTION_EXPANSION[topicId] ?? []);
}
